import 'dart:convert';
import 'dart:io';

/// Path of a fixture generated by the Swift FixtureExporter (`crossplatform/fixtures`).
String fixturePath(String name) {
  for (final c in ['../fixtures/$name', 'fixtures/$name', '../../fixtures/$name']) {
    if (File(c).existsSync()) return c;
  }
  throw StateError('Fixture not found: $name (cwd ${Directory.current.path})');
}

Object? loadFixture(String name) => jsonDecode(File(fixturePath(name)).readAsStringSync());

List<Map<String, Object?>> casesOf(Object? list) =>
    (list as List).map((e) => (e as Map).cast<String, Object?>()).toList();

/// Same comparison as gym_core's tests: numbers to the last bits (max 1 µs absolute); a key Swift
/// omits must be absent (explicit null is a difference); an explicit null in the fixture matches
/// null or absent.
List<String> jsonDiff(Object? actual, Object? expected, [String path = r'$']) {
  final diffs = <String>[];
  void walk(Object? a, Object? e, String p) {
    if (e is num && a is num) {
      final x = a.toDouble(), y = e.toDouble();
      final rel = 1e-12 * (y.abs() > 1 ? y.abs() : 1);
      if (x == y || (x - y).abs() <= (rel < 1e-6 ? rel : 1e-6)) return;
      diffs.add('$p: $a != $e');
      return;
    }
    if (e is Map && a is Map) {
      for (final k in {...e.keys, ...a.keys}) {
        if (!e.containsKey(k) && a.containsKey(k) && a[k] == null) {
          diffs.add('$p.$k: explicit null (Swift omits the key)');
          continue;
        }
        walk(a[k], e[k], '$p.$k');
      }
      return;
    }
    if (e is List && a is List) {
      if (a.length != e.length) {
        diffs.add('$p: length ${a.length} != ${e.length} (actual ${jsonEncode(a)})');
        return;
      }
      for (var i = 0; i < e.length; i++) {
        walk(a[i], e[i], '$p[$i]');
      }
      return;
    }
    if (a != e) diffs.add('$p: ${jsonEncode(a)} != ${jsonEncode(e)}');
  }

  walk(actual, expected, path);
  return diffs;
}
